/// `Tx1dType`: DCT, ADST, FLIPADST, IDENTITY.
pub const DCT: u8 = 0;
pub const ADST: u8 = 1;
pub const FLIPADST: u8 = 2;
pub const IDENTITY: u8 = 3;

fn identity(c: &mut [i32], o: isize, s: isize, n: usize) {
    for i in 0..n as isize {
        let p = idx(o, s, i);
        let v = c[p];
        c[p] = match n {
            4 => v + ((v * 1697 + 2048) >> 12),
            8 => v * 2,
            16 => 2 * v + ((v * 1697 + 1024) >> 11),
            _ => v * 4,
        };
    }
}

/// `dav1d_tx1d_fns[lsz][typ]` applied to `c[o + k * s]`.
pub fn tx1d(lsz: usize, typ: u8, c: &mut [i32], o: isize, s: isize, min: i32, max: i32) {
    let n = 4usize << lsz;
    match (lsz, typ) {
        (0, DCT) => dct4_internal(c, o, s, min, max, false),
        (1, DCT) => dct8_internal(c, o, s, min, max, false),
        (2, DCT) => dct16_internal(c, o, s, min, max, false),
        (3, DCT) => dct32_internal(c, o, s, min, max, false),
        (4, DCT) => dct64(c, o, s, min, max),
        (0, ADST) => adst4_internal(c, o, s, min, max, o, s),
        (1, ADST) => adst8_internal(c, o, s, min, max, o, s),
        (2, ADST) => adst16_internal(c, o, s, min, max, o, s),
        (0, FLIPADST) => adst4_internal(c, o, s, min, max, o + 3 * s, -s),
        (1, FLIPADST) => adst8_internal(c, o, s, min, max, o + 7 * s, -s),
        (2, FLIPADST) => adst16_internal(c, o, s, min, max, o + 15 * s, -s),
        (_, IDENTITY) => identity(c, o, s, n),
        _ => unreachable!("1-D transform {typ} of size {n}"),
    }
}

/// `dav1d_inv_wht4_1d_c`.
pub fn wht4(c: &mut [i32], o: isize, s: isize) {
    let in0 = c[idx(o, s, 0)];
    let in1 = c[idx(o, s, 1)];
    let in2 = c[idx(o, s, 2)];
    let in3 = c[idx(o, s, 3)];
    let t0 = in0 + in1;
    let t2 = in2 - in3;
    let t4 = (t0 - t2) >> 1;
    let t3 = t4 - in3;
    let t1 = t4 - in1;
    c[idx(o, s, 0)] = t0 - t3;
    c[idx(o, s, 1)] = t3;
    c[idx(o, s, 2)] = t1;
    c[idx(o, s, 3)] = t2 + t1;
}

